/**
 * Browsers API module
 * Handles all browser-related API operations: list, CRUD, navigate, screenshot, etc.
 */

export const browsersModule = (API) => ({
  // ── List & Retrieval ───────────────────────────────────────────────────

  /**
   * List all browsers with optional filters
   */
  async list(filters) {
    let qs = ""
    if (filters) {
      const params = Object.entries(filters)
        .map(([key, value]) => `${encodeURIComponent(key)}=${encodeURIComponent(value)}`)
        .join("&")
      qs = `?${params}`
    }
    return API.get(`/api/browsers${qs}`)
  },

  /**
   * Get a specific browser by ID
   */
  async get(browserId) {
    return API.get(`/api/browsers/${browserId}`)
  },

  /**
   * Get browser status by ID
   */
  async getStatus(browserId) {
    return API.get(`/api/browsers/${browserId}/status`)
  },

  // ── CRUD Operations ────────────────────────────────────────────────────

  /**
   * Create a new browser instance
   * @param {Object} browserConfig - Browser configuration (profile, headless, etc.)
   */
  async create(browserConfig) {
    return API.post('/api/browsers', browserConfig)
  },

  /**
   * Update browser configuration
   */
  async update(browserId, browserConfig) {
    return API.put(`/api/browsers/${browserId}`, browserConfig)
  },

  /**
   * Delete a browser instance
   */
  async delete(browserId) {
    return API.delete(`/api/browsers/${browserId}`)
  },

  // ── Browser Navigation & Actions ───────────────────────────────────────

  /**
   * Navigate to a URL
   */
  async navigate(browserId, url) {
    return API.post(`/api/browsers/${browserId}/navigate`, { url })
  },

  /**
   * Get current page URL
   */
  async getCurrentUrl(browserId) {
    return API.get(`/api/browsers/${browserId}/current-url`)
  },

  /**
   * Get page title
   */
  async getPageTitle(browserId) {
    return API.get(`/api/browsers/${browserId}/page-title`)
  },

  /**
   * Go back (previous page)
   */
  async goBack(browserId) {
    return API.post(`/api/browsers/${browserId}/back`, {})
  },

  /**
   * Go forward (next page)
   */
  async goForward(browserId) {
    return API.post(`/api/browsers/${browserId}/forward`, {})
  },

  /**
   * Refresh the page
   */
  async refresh(browserId) {
    return API.post(`/api/browsers/${browserId}/refresh`, {})
  },

  // ── Screenshot & Snapshots ─────────────────────────────────────────────

  /**
   * Take a screenshot of the current page
   * @param {string} browserId - Browser ID
   * @param {Object} options - Screenshot options (format, fullPage, etc.)
   */
  async screenshot(browserId, options = {}) {
    return API.post(`/api/browsers/${browserId}/screenshot`, options)
  },

  /**
   * Get screenshot URL
   */
  async getScreenshotUrl(browserId) {
    return API.connection.prepareUrl(`/api/browsers/${browserId}/screenshot`)
  },

  // ── Page Interaction ────────────────────────────────────────────────────

  /**
   * Execute JavaScript in the page context
   */
  async execute(browserId, script) {
    return API.post(`/api/browsers/${browserId}/execute`, { script })
  },

  /**
   * Click an element
   */
  async click(browserId, selector) {
    return API.post(`/api/browsers/${browserId}/click`, { selector })
  },

  /**
   * Type text in an element
   */
  async type(browserId, selector, text) {
    return API.post(`/api/browsers/${browserId}/type`, { selector, text })
  },

  /**
   * Fill form field
   */
  async fill(browserId, selector, value) {
    return API.post(`/api/browsers/${browserId}/fill`, { selector, value })
  },

  /**
   * Get element text
   */
  async getElementText(browserId, selector) {
    return API.get(`/api/browsers/${browserId}/element-text?selector=${encodeURIComponent(selector)}`)
  },

  /**
   * Get element HTML
   */
  async getElementHtml(browserId, selector) {
    return API.get(`/api/browsers/${browserId}/element-html?selector=${encodeURIComponent(selector)}`)
  },

  /**
   * Check if element exists
   */
  async elementExists(browserId, selector) {
    return API.get(`/api/browsers/${browserId}/element-exists?selector=${encodeURIComponent(selector)}`)
  },

  /**
   * Wait for element to appear
   */
  async waitForElement(browserId, selector, timeout = 30000) {
    return API.post(`/api/browsers/${browserId}/wait-for-element`, { selector, timeout })
  },

  // ── Cookie & Storage Management ────────────────────────────────────────

  /**
   * Get all cookies
   */
  async getCookies(browserId) {
    return API.get(`/api/browsers/${browserId}/cookies`)
  },

  /**
   * Set a cookie
   */
  async setCookie(browserId, cookie) {
    return API.post(`/api/browsers/${browserId}/cookies`, cookie)
  },

  /**
   * Delete a cookie
   */
  async deleteCookie(browserId, name) {
    return API.delete(`/api/browsers/${browserId}/cookies?name=${encodeURIComponent(name)}`)
  },

  /**
   * Clear all cookies
   */
  async clearCookies(browserId) {
    return API.post(`/api/browsers/${browserId}/cookies/clear`, {})
  },

  /**
   * Get local storage
   */
  async getLocalStorage(browserId) {
    return API.get(`/api/browsers/${browserId}/storage/local`)
  },

  /**
   * Set local storage value
   */
  async setLocalStorage(browserId, key, value) {
    return API.post(`/api/browsers/${browserId}/storage/local`, { key, value })
  },

  /**
   * Delete local storage value
   */
  async deleteLocalStorage(browserId, key) {
    return API.delete(`/api/browsers/${browserId}/storage/local?key=${encodeURIComponent(key)}`)
  },

  /**
   * Clear local storage
   */
  async clearLocalStorage(browserId) {
    return API.post(`/api/browsers/${browserId}/storage/local/clear`, {})
  },

  // ── Page Analysis ──────────────────────────────────────────────────────

  /**
   * Get page HTML content
   */
  async getPageContent(browserId) {
    return API.get(`/api/browsers/${browserId}/page-content`)
  },

  /**
   * Get all links on the page
   */
  async getLinks(browserId) {
    return API.get(`/api/browsers/${browserId}/links`)
  },

  /**
   * Get all images on the page
   */
  async getImages(browserId) {
    return API.get(`/api/browsers/${browserId}/images`)
  },

  /**
   * Get page metadata
   */
  async getMetadata(browserId) {
    return API.get(`/api/browsers/${browserId}/metadata`)
  },

  /**
   * Search for text on page
   */
  async findText(browserId, text) {
    return API.get(`/api/browsers/${browserId}/find-text?text=${encodeURIComponent(text)}`)
  },

  // ── Message Handling (Chat Integration) ─────────────────────────────────

  /**
   * Send a message to the browser (for chat integration)
   */
  async message(chat) {
    return API.post('/api/browser', chat)
  }
})

import axios from 'axios'
import { CodxJuniorConnection } from './connection'
import { SocketManager } from './socket'
import { filesModule } from './modules/files'
import { globalSettingsModule } from './modules/globalSettings'
import { analyticsModule } from './modules/analytics'
import { logsModule } from './modules/logs'
import { viewsModule } from './modules/views'
import { chatsModule } from './modules/chats'
import { workspacesModule } from './modules/workspaces'
import { browsersModule } from './modules/browsers'

/**
 * In-flight request deduplication map.
 * Key: "METHOD:url:serialized_body"
 * Value: Promise
 */
const _inflightRequests = new Map()

/**
 * Static, singleton socket manager shared across all API instances.
 */
let _staticSocketManager = null

/**
 * Build a stable cache key for a request.
 */
function _requestKey(method, url, data) {
  const body = data !== undefined ? JSON.stringify(data) : ''
  return `${method.toUpperCase()}:${url}:${body}`
}

/**
 * Wrap a request factory in deduplication logic.
 * If an identical request is already in-flight, the new caller
 * receives the same Promise (and therefore the same resolved value).
 */
function _dedupedRequest(method, url, data, requestFn) {
  const key = _requestKey(method, url, data)

  if (_inflightRequests.has(key)) {
    return _inflightRequests.get(key)
  }

  const promise = requestFn().finally(() => {
    _inflightRequests.delete(key)
  })

  _inflightRequests.set(key, promise)
  return promise
}

const initializeAPI = ({ project, user } = {}) => {
  const API = {
    sid: "",
    connection: null,
    _user: user,

    get user () {
      return API._user
    },
    set user(user) {
      API._user = user
      API.initConnection()
    },

    _activeProject: project,
    get activeProject() {
      return this._activeProject
    },
    set activeProject(value) {
      this._activeProject = value
      API.initConnection()
    },

    set interceptors(value) {
      Object.assign(this.connection.interceptors, value)
    },

    initConnection() {
      API.connection = new CodxJuniorConnection({
        settings: API.activeProject,
        user: API.user
      })
    },

    // ─── HTTP helpers ────────────────────────────────────────────────────────

    get(url) {
      return _dedupedRequest('GET', API.connection.prepareUrl(url), undefined, () => API.connection.get(url))
    },
    del(url) {
      return _dedupedRequest('DEL', API.connection.prepareUrl(url), undefined, () => API.connection.del(url))
    },
    post(url, data) {
      return _dedupedRequest('POST', API.connection.prepareUrl(url), data, () => API.connection.post(url, data))
    },
    put(url, data) {
      return _dedupedRequest('PUT', API.connection.prepareUrl(url), data, () => API.connection.put(url, data))
    },
    delete(url) {
      return _dedupedRequest('DELETE', API.connection.prepareUrl(url), undefined, () => API.connection.delete(url))
    },

    // ─── Socket management (static/singleton) ────────────────────────────────

    initSocket({ onConnect, onDisconnect, onEvent } = {}) {
      if (_staticSocketManager) {
        _staticSocketManager.disconnect()
      }

      _staticSocketManager = new SocketManager({
        onConnect(socketId) {
          API.sid = socketId
          if (typeof onConnect === 'function') onConnect(socketId)
        },
        onDisconnect() {
          API.sid = ''
          if (typeof onDisconnect === 'function') onDisconnect()
        },
        onEvent(payload) {
          if (typeof onEvent === 'function') onEvent(payload)
        }
      })

      _staticSocketManager.connect()
      return _staticSocketManager
    },

    get socket() {
      return _staticSocketManager
    },

    disconnectSocket() {
      if (_staticSocketManager) {
        _staticSocketManager.disconnect()
        _staticSocketManager = null
      }
    },

    // ─── Domain helpers ──────────────────────────────────────────────────────

    oauth: {
      async getOAuthLoginUrl(provider) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${provider}`)
        return await API.get(`/api/users/oauth-login-url/${provider}?redirect_uri=${redirect_uri}`)
      },
      async oauthLogin({ oauth_provider, code, state }) {
        const redirect_uri = encodeURIComponent(window.location.origin + `/auth/${oauth_provider}`)
        const data = await API.post('/api/users/oauth-login', {
          oauth_provider,
          code,
          state,
          redirect_uri
        })
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data
      }
    },
    users: {
      async list() {
        API.userNetwork = await API.get('/api/users')
        return API.userNetwork
      },
      async login(user) {
        if (!user) {
          try {
            user = API.user = JSON.parse(localStorage.getItem("CODX_USER"))
            API.initConnection()
          } catch {}
          if (!user) return null
        }
        const data = await API.post('/api/users/login', user)
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        await API.onUserLogin()
        return data
      },
      async save(user) {
        const data = await API.put('/api/users', user)
        API.user = data
        localStorage.setItem("CODX_USER", JSON.stringify(API.user))
        return data
      },
      async logout() {
        API.user = null
        API.activeProject = {}
        localStorage.removeItem("CODX_USER")
      },
      async refreshInfo() {
        const data = await API.get('/api/users/me/refresh')
        if (data && API.user) {
          API.user = {
            ...API.user,
            token_usage_today: data.token_usage_today,
            token_limits_today: data.token_limits_today,
            token_limit_rules: data.token_limit_rules,
            token_limit_requests: data.token_limit_requests,
          }
        }
        return data
      }
    },
    apps: {
      async list() {
        const apps = await API.get('/api/apps')
        return apps
      },
      async run(appName) {
        const data = await API.get(`/api/apps/run?app=${appName}`)
        return data
      },
      async runScript(script) {
        const data = await API.post('/api/run/script', { script })
        return data
      }
    },
    async project(projectOrId) {
      if (!projectOrId.codx_path) {
        const existingProject = API.allProjects.find(p => p.id === projectOrId || p.project_name === projectOrId)
        if (!existingProject) {
          throw new Error("Invalid projectOrId: " + JSON.stringify(projectOrId))
        }
        projectOrId = existingProject
      }
      if (projectOrId.codx_path === API.settings.codx_path) {
        return API
      }
      return initializeAPI({ ...API, project: projectOrId })
    },
    projects: {
      async list(withMetrics) {
        const { projects, workspaces } = await API.get(`/api/projects?with_metrics=${withMetrics ? 1 : 0}`)
        API.allProjects = projects
        API.allWorkspaces = workspaces
        API.allProjects.forEach(p => {
          const projectPath = p.abs_project_path
          p.parentProject = API.allProjects
            .filter(p => p.abs_project_path != projectPath && projectPath.startsWith(p.abs_project_path))
            .sort((a, b) => a.abs_project_path > b.abs_project_path ? -1 : 1)[0]
        })
        return API.allProjects
      },
      create(projectPath) {
        return API.post('/api/projects?project_path=' + encodeURIComponent(projectPath), {})
      },
      delete() {
        localStorage.setItem("API_SETTINGS", "")
        API.del('/api/projects')
        API.activeProject = null
      },
      async readme() {
        const data = await API.get('/api/projects/readme')
        return data
      },
      async watch(watching) {
        const settings = await API.settings.read()
        settings.watching = watching
        API.settings.save(settings)
      },
      test() {
        return API.get('/api/project/script/test')
      },
      loadIssue(url) {
        return API.get('/api/github/issues/read?issue_url=' + encodeURIComponent(url))
      },
      ai: {
