### 2. Create Session List Component

```vue src/components/browsers/BrowserSessionList.vue
<script setup>
import { ref, computed, onMounted } from 'vue'
import { $storex } from '@/store'

const sessions = computed(() => $storex.browsers.allSessions)
const selectedSessionId = computed(() => $storex.browsers.selectedSessionId)
const isLoading = computed(() => $storex.browsers.isLoading)
const showNewForm = computed(() => $storex.browsers.showNewSessionForm)
const isMobile = computed(() => $storex.ui.isMobile)

const newSessionName = ref('')
const newSessionUrl = ref('http://example.com')
const newSessionHeadless = ref(false)

onMounted(() => {
  $storex.browsers.loadSessions()
})

const handleSelectSession = (sessionId) => {
  $storex.browsers.selectSession(sessionId)
}

const handleCreateSession = async () => {
  if (!newSessionName.value.trim()) {
    $storex.ui.addNotification({ 
      text: 'Session name is required',
      type: 'warning'
    })
    return
  }

  try {
    await $storex.browsers.createSession({
      name: newSessionName.value.trim(),
      url: newSessionUrl.value || 'http://example.com',
      headless: newSessionHeadless.value
    })
    newSessionName.value = ''
    newSessionUrl.value = 'http://example.com'
    newSessionHeadless.value = false
  } catch (error) {
    console.error('Failed to create session:', error)
  }
}

const handleDeleteSession = async (sessionId, event) => {
  event.stopPropagation()
  if (!confirm('Are you sure you want to delete this session?')) return

  try {
    await $storex.browsers.deleteSession(sessionId)
  } catch (error) {
    console.error('Failed to delete session:', error)
  }
}

const handleRunSession = async (sessionId, event) => {
  event.stopPropagation()
  try {
    await $storex.browsers.runSession(sessionId)
  } catch (error) {
    console.error('Failed to run session:', error)
  }
}

const toggleNewForm = () => {
  $storex.browsers.toggleNewSessionForm()
}
</script>

