<script setup>
import { ref, computed, watch } from 'vue'
import { $storex } from '@/store'

const selectedSession = computed(() => $storex.browsers.selectedSession)
const editingSessionId = computed(() => $storex.browsers.editingSessionId)
const isEditing = computed(() => editingSessionId.value !== null)
const isMobile = computed(() => $storex.ui.isMobile)

const editFormData = ref({})
const saving = ref(false)

// Watch for editing session changes
watch(editingSessionId, (newId) => {
  if (newId) {
    const session = $storex.browsers.sessionById(newId)
    if (session) {
      editFormData.value = { ...session }
    }
  } else {
    editFormData.value = {}
  }
})

const handleSaveSession = async () => {
  if (!editFormData.value.name?.trim()) {
    $storex.ui.addNotification({ 
      text: 'Session name is required',
      type: 'warning'
    })
    return
  }

  saving.value = true
  try {
    await $storex.browsers.updateSession(editFormData.value)
  } catch (error) {
    console.error('Failed to save session:', error)
  } finally {
    saving.value = false
  }
}

const handleCancelEdit = () => {
  $storex.browsers.stopEditingSession()
  editFormData.value = {}
}

const handleRunSession = async () => {
  if (selectedSession.value?.id) {
    try {
      await $storex.browsers.runSession(selectedSession.value.id)
    } catch (error) {
      console.error('Failed to run session:', error)
    }
  }
}
</script>

