import { getterTree, mutationTree, actionTree } from 'typed-vuex'
import { $storex } from '.'
import { API } from '../api/api'

export const namespaced = true

export const state = () => ({
  sessions: [],
  selectedSessionId: null,
  loading: false,
  error: null,
  editingSessionId: null,
  showNewSessionForm: false
})

export const getters = getterTree(state, {
  allSessions: state => state.sessions,

  selectedSession: state => {
    if (!state.selectedSessionId) return null
    return state.sessions.find(s => s.id === state.selectedSessionId)
  },

  sessionById: (state) => (id) => {
    return state.sessions.find(s => s.id === id)
  },

  isLoading: state => state.loading,
  hasError: state => !!state.error,
  errorMessage: state => state.error
})

export const mutations = mutationTree(state, {
  setSessions(state, sessions) {
    state.sessions = sessions
  },

  addSession(state, session) {
    state.sessions.push(session)
  },

  updateSession(state, session) {
    const index = state.sessions.findIndex(s => s.id === session.id)
    if (index !== -1) {
      state.sessions[index] = session
    }
  },

  deleteSession(state, sessionId) {
    state.sessions = state.sessions.filter(s => s.id !== sessionId)
    if (state.selectedSessionId === sessionId) {
      state.selectedSessionId = null
    }
  },

  selectSession(state, sessionId) {
    state.selectedSessionId = sessionId
  },

  clearSelection(state) {
    state.selectedSessionId = null
  },

  setLoading(state, loading) {
    state.loading = loading
  },

  setError(state, error) {
    state.error = error
  },

  clearError(state) {
    state.error = null
  },

  setEditingSession(state, sessionId) {
    state.editingSessionId = sessionId
  },

  clearEditingSession(state) {
    state.editingSessionId = null
  },

  toggleNewSessionForm(state, show) {
    state.showNewSessionForm = show !== undefined ? show : !state.showNewSessionForm
  }
})

export const actions = actionTree(
  { state, getters, mutations },
  {
    async loadSessions({ commit }) {
      commit('setLoading', true)
      commit('clearError')
      try {
        const sessions = await API.browsers.list()
        commit('setSessions', sessions || [])
      } catch (error) {
        commit('setError', error.message || 'Failed to load sessions')
        console.error('[Browsers] Error loading sessions:', error)
      } finally {
        commit('setLoading', false)
      }
    },

    async createSession({ commit }, sessionData) {
      commit('clearError')
      try {
        const session = await API.browsers.create(sessionData)
        commit('addSession', session)
        commit('toggleNewSessionForm', false)
        $storex.ui.addNotification({
          text: `Browser session "${session.name}" created`,
          type: 'success'
        })
        return session
      } catch (error) {
        commit('setError', error.message || 'Failed to create session')
        $storex.ui.addNotification({
          text: error.message || 'Failed to create session',
          type: 'error'
        })
        throw error
      }
    },

    async updateSession({ commit }, sessionData) {
      commit('clearError')
      try {
        const session = await API.browsers.update(sessionData.id, sessionData)
        commit('updateSession', session)
        commit('clearEditingSession')
        $storex.ui.addNotification({
          text: `Browser session "${session.name}" updated`,
          type: 'success'
        })
        return session
      } catch (error) {
        commit('setError', error.message || 'Failed to update session')
        $storex.ui.addNotification({
          text: error.message || 'Failed to update session',
          type: 'error'
        })
        throw error
      }
    },

    async deleteSession({ commit }, sessionId) {
      commit('clearError')
      try {
        await API.browsers.delete(sessionId)
        commit('deleteSession', sessionId)
        $storex.ui.addNotification({
          text: 'Browser session deleted',
          type: 'success'
        })
      } catch (error) {
        commit('setError', error.message || 'Failed to delete session')
        $storex.ui.addNotification({
          text: error.message || 'Failed to delete session',
          type: 'error'
        })
        throw error
      }
    },

    selectSession({ commit }, sessionId) {
      commit('selectSession', sessionId)
    },

    clearSelection({ commit }) {
      commit('clearSelection')
    },

    toggleNewSessionForm({ commit }, show) {
      commit('toggleNewSessionForm', show)
      if (show) {
        commit('clearEditingSession')
      }
    },

    startEditingSession({ commit }, sessionId) {
      commit('setEditingSession', sessionId)
    },

    stopEditingSession({ commit }) {
      commit('clearEditingSession')
    },

    async runSession({ commit }, sessionId) {
      try {
        const session = await API.browsers.get(sessionId)
        if (!session) throw new Error('Session not found')

        // Open session in AppWindow
        $storex.ui.showApp({
          tabId: `browser-${sessionId}`,
          name: session.name,
          component: 'browser-viewer',
          params: {
            sessionId: sessionId,
            session: session
          }
        })

        return session
      } catch (error) {
        commit('setError', error.message || 'Failed to run session')
        $storex.ui.addNotification({
          text: error.message || 'Failed to run session',
          type: 'error'
        })
        throw error
      }
    }
  }
)

export default function Navigate({ $router, $storex }) {

  // ════════════════════════════════════════════════════════════════
  // ROUTE BUILDERS - Centralized route path generation
  // ════════════════════════════════════════════════════════════════

  const routes = {
    chat: {
      list: () => ({ name: 'chats' }),
      open: (chatId, chatName) => ({
        name: 'chat',
        params: { chatId, chatName }
      }),
      openWithWorkspace: (chatId, chatName, workspaceId, workspaceName) => ({
        name: 'chat-workspace',
        params: { chatId, chatName, workspaceId, workspaceName }
      })
    },
    workspace: {
      list: () => ({ name: 'workspaces' }),
      open: (workspaceId, workspaceName) => ({
        name: 'workspace',
        params: { workspaceId, workspaceName }
      })
    },
    browser: {
      list: () => ({ name: 'browsers' }),
      open: (sessionId, sessionName) => ({
        name: 'browser-session',
        params: { sessionId, sessionName }
      })
    },
    kanban: {
      open: () => ({ name: 'kanban' })
    },
    messenger: {
      open: () => ({ name: 'messenger' })
    },
    desktop: {
      open: () => ({ name: 'codx-junior-split' })
    },
    mobile: {
      open: () => ({ name: 'mobile' })
    },
    home: {
      open: () => ({ name: 'home' })
    }
  }

  // ════════════════════════════════════════════════════════════════
  // STATE GETTERS
  // ════════════════════════════════════════════════════════════════

  const $navigation = {
    get activeProject() {
      return $storex.projects.activeProject
    },

    get isDesktopMode() {
      return $router.currentRoute.value.name === 'codx-junior-split'
    },

    get isMobileMode() {
      return $router.currentRoute.value.name === 'mobile'
    },

    get isChatView() {
      const name = $router.currentRoute.value.name
      return name === 'chat' || name === 'chat-workspace'
    },

    get isWorkspaceView() {
      const name = $router.currentRoute.value.name
      return name === 'workspace' || name === 'workspaces'
    },

    get isBrowserView() {
      const name = $router.currentRoute.value.name
      return name === 'browsers' || name === 'browser-session'
    },

    get isKanbanView() {
      return $router.currentRoute.value.name === 'kanban'
    },

    get isMessengerView() {
      return $router.currentRoute.value.name === 'messenger'
    },

    get isHomeView() {
      return $router.currentRoute.value.name === 'home'
    },

    getCurrentRoute() {
      return $router.currentRoute.value
    },

    getChatId() {
      return $router.currentRoute.value.params.chatId || null
    },

    getChatName() {
      return $router.currentRoute.value.params.chatName || null
    },

    getWorkspaceId() {
      return $router.currentRoute.value.params.workspaceId || null
    },

    getWorkspaceName() {
      return $router.currentRoute.value.params.workspaceName || null
    },

    getSessionId() {
      return $router.currentRoute.value.params.sessionId || null
    },

    getSessionName() {
      return $router.currentRoute.value.params.sessionName || null
    },

    get hasChatContext() {
      return this.getChatId() !== null
    },

    get hasWorkspaceContext() {
      return this.getWorkspaceId() !== null
    },

    get hasSessionContext() {
      return this.getSessionId() !== null
    },

    // ════════════════════════════════════════════════════════════════
    // INITIALIZATION
    // ════════════════════════════════════════════════════════════════

    init() {
      // Initialize history state on first load
      if (window.history.length === 1) {
        window.history.replaceState(null, '', '/')
        window.history.pushState(null, '', window.location.href)
      }
    },

    async onRouteChanged({ from, to }) {
      // ── OAuth callback ────────────────────────────────────────────
      if (to.path.startsWith('/auth')) {
        const { code, state } = to.query
        const provider = to.path.split('/').reverse()[0]

        if (!provider || !code) {
          $storex.session.onError('Missing OAuth provider or code')
          return '/'
        }

        try {
          await $storex.users.oauthLogin({ provider, code, state })
          return '/'
        } catch (error) {
          $storex.session.onError('Failed to complete OAuth login')
          return '/'
        }
      }

      // ── Standalone routes with name (opt-out of mobile/desktop redirect) ─
      if (!!to.name) {
        return true
      }

      // ── Mobile redirect ──────────────────────────────────────────
      if ($storex.ui.isMobile && to.name !== 'mobile') {
        return { name: 'mobile', replace: true }
      }

      // ── Desktop: redirect /mobile → home ─────────────────────────
      if (!$storex.ui.isMobile && to.name === 'mobile') {
        return { name: 'home', replace: true }
      }

      return true
    },

    // ════════════════════════════════════════════════════════════════
    // CHAT NAVIGATION
    // ════════════════════════════════════════════════════════════════

    chats: {
      list() {
        $router.push(routes.chat.list())
      },

      open(chatId, chatName) {
        if (!chatId) {
          console.warn('[Navigation] chats.open: invalid chatId', chatId)
          return
        }

        const name = chatName || `chat-${chatId}`

        if ($navigation.isDesktopMode) {
          // Desktop mode: show as app panel
          $storex.ui.showApp({
            tabId: chatId,
            name: name,
            component: 'chat',
            params: {
              chat: {
                id: chatId,
                name: name,
                owner_project_id: $navigation.activeProject?.project_id
              }
            }
          })
        } else {
          // Router mode: push to chat route
          $router.push(routes.chat.open(chatId, name))
        }
      },

      openWithWorkspace(chatId, chatName, workspaceId, workspaceName) {
        if (!chatId || !workspaceId) {
          console.warn('[Navigation] chats.openWithWorkspace: invalid chat or workspace', { chatId, workspaceId })
          return
        }

        const chatName_ = chatName || `chat-${chatId}`
        const workspaceName_ = workspaceName || `workspace-${workspaceId}`

        if ($navigation.isDesktopMode) {
          // Desktop mode: show chat with workspace context
          $storex.ui.showApp({
            tabId: chatId,
            name: chatName_,
            component: 'chat',
            params: {
              chat: {
                id: chatId,
                name: chatName_,
                owner_project_id: $navigation.activeProject?.project_id
              },
              workspace: {
                id: workspaceId,
                name: workspaceName_
              }
            }
          })
        } else {
          // Router mode: push to chat-workspace route
          $router.push(routes.chat.openWithWorkspace(chatId, chatName_, workspaceId, workspaceName_))
        }
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE NAVIGATION
    // ════════════════════════════════════════════════════════════════

    workspaces: {
      list() {
        if ($navigation.isDesktopMode) {
          // Desktop mode: show as app panel
          $storex.ui.showApp({
            tabId: 'workspaces',
            name: 'Workspaces',
            component: 'workspaces',
            params: {}
          })
        } else {
          // Router mode: navigate to route
          $router.push(routes.workspace.list())
        }
      },

      open(workspaceId, workspaceName) {
        if (!workspaceId) {
          console.warn('[Navigation] workspaces.open: invalid workspaceId', workspaceId)
          return
        }

        const name = workspaceName || `workspace-${workspaceId}`

        // Check if currently in chat view
        if ($navigation.isChatView) {
          // In chat view: open workspace with chat context
          const chatId = $navigation.getChatId()
          const chatName = $navigation.getChatName()

          if (chatId) {
            $navigation.chats.openWithWorkspace(chatId, chatName, workspaceId, name)
            return
          }
        }

        // Not in chat view: open workspace normally
        if ($navigation.isDesktopMode) {
          // Desktop mode: show as app panel
          $storex.ui.showApp({
            tabId: `workspace-${workspaceId}`,
            name: name,
            component: 'workspace',
            params: {
              workspace: {
                id: workspaceId,
                name: name
              }
            }
          })
        } else {
          // Router mode: navigate to workspace route
          $router.push(routes.workspace.open(workspaceId, name))
        }
      }
    },

    // ════════════════════════════════════════════════════════════════
    // BROWSER NAVIGATION
    // ════════════════════════════════════════════════════════════════

    browsers: {
      list() {
        if ($navigation.isDesktopMode) {
          // Desktop mode: show as app panel
          $storex.ui.showApp({
            tabId: 'browsers',
            name: 'Browser Sessions',
            component: 'browsers',
            params: {}
          })
        } else {
          // Router mode: navigate to route
          $router.push(routes.browser.list())
        }
      },

      open(sessionId, sessionName) {
        if (!sessionId) {
          console.warn('[Navigation] browsers.open: invalid sessionId', sessionId)
          return
        }

        const name = sessionName || `session-${sessionId}`

        if ($navigation.isDesktopMode) {
          // Desktop mode: show session viewer
          $storex.ui.showApp({
            tabId: `browser-${sessionId}`,
            name: name,
            component: 'browser-viewer',
            params: {
              sessionId: sessionId,
              session: {
                id: sessionId,
                name: name
              }
            }
          })
        } else {
          // Router mode: navigate to session route
          $router.push(routes.browser.open(sessionId, name))
        }
      }
    },

    // ════════════════════════════════════════════════════════════════
    // PRIMARY APP NAVIGATION
    // ════════════════════════════════════════════════════════════════

    apps: {
      openHome() {
        $router.push(routes.home.open())
      },

      openDesktop() {
        $router.push(routes.desktop.open())
      },

      openMessenger() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'messenger',
            name: 'Messenger',
            component: 'messenger',
            params: {}
          })
        } else {
          $router.push(routes.messenger.open())
        }
      },

      openKanban() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showTab('tasks')
        } else {
          $router.push(routes.kanban.open())
        }
      },

      openMobile() {
        $router.push(routes.mobile.open())
      },

      openFileExplorer() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showTab('files')
        } else {
          $router.push({ path: '/files' })
        }
      },

      openWiki() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showTab('wiki')
        } else {
          $router.push({ path: '/wiki' })
        }
      },

      openTeam() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'team',
            name: 'Team',
            component: 'team',
            params: {}
          })
        } else {
          $router.push({ path: '/team' })
        }
      },

      openViews() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'views',
            name: 'Views',
            component: 'views',
            params: {}
          })
        } else {
          $router.push({ path: '/views' })
        }
      },

      openProfiles() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'profiles',
            name: 'Profiles',
            component: 'profiles',
            params: {}
          })
        } else {
          $router.push({ path: '/profiles' })
        }
      },

      openKnowledge() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'knowledge',
            name: 'Knowledge',
            component: 'knowledge',
            params: {}
          })
        } else {
          $router.push({ path: '/knowledge' })
        }
      },

      openAnalytics() {
        if ($navigation.isDesktopMode) {
          $storex.ui.showApp({
            tabId: 'analytics',
            name: 'Analytics',
            component: 'analytics',
            params: {}
          })
        } else {
          $router.push({ path: '/analytics' })
        }
      }
    },

    // ════════════════════════════════════════════════════════════════
    // WORKSPACE CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    workspace: {
      getCurrentWorkspace() {
        const workspaceId = $navigation.getWorkspaceId()
        const workspaceName = $navigation.getWorkspaceName()

        if (workspaceId) {
          return { id: workspaceId, name: workspaceName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasWorkspaceContext
      }
    },

    // ════════════════════════════════════════════════════════════════
    // SESSION CONTEXT (for reading current state)
    // ════════════════════════════════════════════════════════════════

    session: {
      getCurrentSession() {
        const sessionId = $navigation.getSessionId()
        const sessionName = $navigation.getSessionName()

        if (sessionId) {
          return { id: sessionId, name: sessionName }
        }
        return null
      },

      hasContext() {
        return $navigation.hasSessionContext
      }
    }
  }

  return $navigation
}

import { createRouter, createWebHistory } from 'vue-router'
import { $storex } from '../store'
import Navigate from './navigate'
import QuickChatView from '@/views/QuickChatView.vue'
import WorkspaceView from '@/views/WorkspaceView.vue'
import MessengerView from '@/views/MessengerView.vue'
import MetricsDashboard from '@/components/analytics/MetricsDashboard.vue'
import Desktop from '@/components/desktop/Desktop.vue'
import KanbanBoardView from '@/components/kanban/board/KanbanBoardView.vue'
import BrowsersSessionManager from '@/components/browsers/BrowsersSessionManager.vue'

const router = createRouter({
  history: createWebHistory(import.meta.env.BASE_URL),
  routes: [
    {
      // Teams-like launcher home page
      path: '/',
      name: 'home',
      component: QuickChatView
    },
    {
      // Chat routes: router mode
      path: '/chats',
      name: 'chats',
      component: QuickChatView
    },
    {
      path: '/chats/:chatId/:chatName',
      name: 'chat',
      component: QuickChatView
    },
    {
      path: '/chats/:chatId/:chatName/workspace/:workspaceId/:workspaceName',
      name: 'chat-workspace',
      component: QuickChatView
    },
    {
      // Workspace routes: router mode
      path: '/workspaces',
      name: 'workspaces',
      component: WorkspaceView
    },
    {
      path: '/workspaces/:workspaceId/:workspaceName',
      name: 'workspace',
      component: WorkspaceView
    },
    {
      // Browser routes: router mode
      path: '/browsers',
      name: 'browsers',
      component: BrowsersSessionManager
    },
    {
      path: '/browsers/:sessionId/:sessionName',
      name: 'browser-session',
      component: BrowsersSessionManager
    },
    {
      path: '/kanban',
      name: 'kanban',
      component: KanbanBoardView
    },
    {
      path: '/messenger',
      name: 'messenger',
      component: MessengerView
    },
    {
      // Desktop / team view (previously the catch-all)
      path: '/desktop/:pathMatch(.*)*',
      name: 'codx-junior-split',
      component: Desktop
    },
    {
      path: '/analytics',
      name: 'analytics',
      component: MetricsDashboard
    },
    {
      // Catch-all: redirect everything else to home
      path: '/:pathMatch(.*)*',
      redirect: '/'
    },
  ]
})

// Initialize navigation API with both $router and $storex
router.$navigation = Navigate({ $router: router, $storex })
router.$navigation.init()

router.beforeEach((to, from) => {
  return router.$navigation.onRouteChanged({ from, to })
})

$storex.$router = router

export default router
